import React, { useEffect, useState } from "react";
import Profile from "../../assets/referrals/profile.png";
import OpenInNewIcon from "@mui/icons-material/OpenInNew";
import { useNavigate } from "react-router-dom";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import { apisPath, paths } from "../../utils/path";
import http from "../../services/utility";

export default function Customer({ navigation }) {
  const navigate = useNavigate();

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.users)
      .then(async (res) => {
        // console.log(res?.data?.users);
        var data = res?.data?.users;

        for (let i = 0; i < data.length; i++) {
          data[i]["first_name"] = data[i]?.name?.split(" ")[0];
          data[i]["last_name"] = data[i]?.name?.split(" ")[1];
        }

        setTableData(data);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const [tableHeader, setTableHeader] = useState([
    { name: "Name" },
    { name: "Email" },
    { name: "Phone Number" },
    { name: "Gender" },
  ]);
  const [tableData, setTableData] = useState([]);

  return (
    <div className="customer">
      <h3 className="customer__heading page_heading">Customer</h3>
      <div className="customer__content">
        <table className="customer__content__table">
          <tr>
            {tableHeader?.map((header, index) => {
              return (
                <th key={index}>
                  <span>
                    {header?.name} <ArrowDropDownIcon />
                  </span>
                </th>
              );
            })}
          </tr>

          {tableData?.map((data, index) => {
            return (
              <tr key={index}>
                <td>
                  <div>
                    <img src={!data?.image ? Profile : data?.image} />
                    {(!data?.first_name && !data?.last_name) ||
                    data?.first_name + data?.last_name === ""
                      ? "Unknown"
                      : (data?.first_name ? data?.first_name : "") +
                        " " +
                        (data?.last_name ? data?.last_name : "")}
                  </div>
                </td>
                <td>
                  {!data?.email || data?.email === "" ? "Unknown" : data?.email}
                </td>
                <td>
                  {!data?.phone || data?.phone === "" ? "0" : data?.phone}
                </td>
                <td>
                  <div>
                    {!data?.gender || data?.gender == ""
                      ? "Unknown"
                      : data?.gender}
                    <OpenInNewIcon
                      sx={{
                        fontSize: 18,
                        color: "red",
                        cursor: "pointer",
                      }}
                      onClick={() =>
                        navigate(`/${paths?.front?.user?.customer}/${index}`, {
                          state: { data: data },
                        })
                      }
                    />
                  </div>
                </td>
              </tr>
            );
          })}
        </table>
      </div>
    </div>
  );
}
